import { Injectable } from '@nestjs/common';
import {
    registerDecorator,
    ValidationArguments,
    ValidationOptions,
    ValidatorConstraint,
    ValidatorConstraintInterface,
} from 'class-validator';

import { CreateOfferingDTO, ValidBillingCycles } from './createOffering.dto.js';
import { OfferingType } from '../entities/OfferingType.js';

@ValidatorConstraint({ name: 'TopUpAmountRule', async: false })
@Injectable()
export class TopUpAmountRule implements ValidatorConstraintInterface {
    validate(topUpAmount: string, args: ValidationArguments) {
        const obj = args.object as CreateOfferingDTO;
        if (obj.billingCycle === ValidBillingCycles.topUp) {
            return topUpAmount !== undefined && topUpAmount !== null && topUpAmount !== '';
        }
        if (topUpAmount !== undefined && topUpAmount !== null && topUpAmount !== '') {
            return false;
        }
        return true;
    }

    defaultMessage(args: ValidationArguments) {
        const obj = args.object as CreateOfferingDTO;
        if (obj.billingCycle === ValidBillingCycles.topUp) {
            return 'topUpAmount is required when billingCycle is topUp';
        }
        return 'topUpAmount is only valid when billingCycle is topUp';
    }
}

@ValidatorConstraint({ name: 'TopUpThresholdRule', async: false })
@Injectable()
export class TopUpThresholdRule implements ValidatorConstraintInterface {
    validate(topUpThreshold: string, args: ValidationArguments) {
        const obj = args.object as CreateOfferingDTO;
        if (topUpThreshold === undefined || topUpThreshold === null || topUpThreshold === '') {
            return true;
        }
        return obj.billingCycle === ValidBillingCycles.topUp;
    }

    defaultMessage() {
        return 'topUpThreshold is only valid when billingCycle is topUp';
    }
}

@ValidatorConstraint({ name: 'TopUpBillingCycleRule', async: false })
@Injectable()
export class TopUpBillingCycleRule implements ValidatorConstraintInterface {
    validate(billingCycle: ValidBillingCycles, args: ValidationArguments) {
        const obj = args.object as CreateOfferingDTO;
        if (billingCycle === ValidBillingCycles.topUp) {
            return obj.offeringType !== OfferingType.subscription;
        }
        return true;
    }

    defaultMessage() {
        return 'Subscription offerings cannot use topUp billing cycle';
    }
}

export function TopUpAmount(validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'topUpAmount',
            target: (object as object).constructor,
            propertyName: propertyName,
            options: validationOptions,
            validator: TopUpAmountRule,
        });
    };
}

export function TopUpThreshold(validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'topUpThreshold',
            target: (object as object).constructor,
            propertyName: propertyName,
            options: validationOptions,
            validator: TopUpThresholdRule,
        });
    };
}

export function TopUpBillingCycle(validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'topUpBillingCycle',
            target: (object as object).constructor,
            propertyName: propertyName,
            options: validationOptions,
            validator: TopUpBillingCycleRule,
        });
    };
}

