export class UsageBased extends Offering {
    static readonly logger = new Logger(UsageBased.name);
    isUnenrollment?: boolean;
    isEnrollment?: boolean;
    async enroll(subject: string, customer?: ReadCustomerResponseData): Promise<void> {
        if (this.billingCycle === ValidBillingCycles.topUp) {
            await this.topUp({ customer });
            return;
        }
        await this.registerBillingSchedule(subject);
        const upfrontPaidDimensions = this.dimensions.filter(
            (dimension) => dimension?.paymentSchedule === PaymentSchedule.upfront,
        );
        if (upfrontPaidDimensions?.length && this.usageOverrides?.length) {
            const currentDimensions = JSON.parse(JSON.stringify(this.dimensions));
            this.dimensions = upfrontPaidDimensions;
            this.isEnrollment = true;
            await this.processBilling(undefined, undefined, customer);
            this.dimensions = currentDimensions;
        }
    }

    async topUp({ customer }: { customer?: ReadCustomerResponseData }): Promise<string | void> {
        const creditService = this.invoicesService.creditService;
        const { balance } = await creditService.findCreditBalance(
            { businessID: this.businessID, customerId: this.customerId },
            false,
        );
        const currentBalance = parseFloat(balance || '0');
        const topUpAmount = parseFloat(this.topUpAmount || '0');
        const topUpThreshold = parseFloat(this.topUpThreshold !== undefined ? this.topUpThreshold : '0.2');
        const thresholdAmount = topUpThreshold * topUpAmount;
        if (currentBalance >= thresholdAmount) {
            return;
        }
        const unitCost = Math.round((topUpAmount - currentBalance) * 100) / 100;
        if (unitCost <= 0) {
            return;
        }
        const lineItems = new InvoiceLineItems();
        lineItems.addLineItem(new InvoiceLineItem(`${this.offeringName} - Top Up`, 1, unitCost));
        const { invoiceId } = await this.invoicesService.create({
            businessID: this.businessID,
            customer,
            customerId: this.customerId,
            items: lineItems,
            invoiceDate: new Date().toISOString(),
            currency: Offering.getCurrency({ customer, offering: this }),
            storePaymentAsCredit: true,
        });
        return invoiceId;
    }

    async processTopUpBilling({
        customer,
        startDate,
        endDate,
    }: {
        customer?: ReadCustomerResponseData;
        startDate?: Date;
        endDate?: Date;
    }): Promise<string | void> {
        const creditService = this.invoicesService.creditService;
        const end = endDate ? endDate : new Date();
        const start = startDate ? startDate : new Date(end.getTime() - 60 * 60 * 1000);
        const lineItems = new InvoiceLineItems();
        await Offering.getLineItemsForUsage({
            startDate: start,
            endDate: end,
            customer,
            lineItems,
            negative: false,
            businessID: this.businessID,
            customerId: this.customerId,
            customerService: this.customerService,
            offeringInstance: this,
            dimensions: this.dimensions,
        });
        const usageTotal = lineItems.getTotal();
        const { balance } = await creditService.findCreditBalance(
            { businessID: this.businessID, customerId: this.customerId },
            false,
        );
        let currentBalance = parseFloat(balance || '0');
        if (usageTotal > 0) {
            await creditService.create(
                {
                    transactionAmount: (-1 * usageTotal).toFixed(2),
                    customerId: this.customerId,
                    businessID: this.businessID,
                    timestamp: new Date().toISOString(),
                    metadata: {
                        reason: `${this.offeringName} hourly usage`,
                        offeringId: this.offeringId,
                    },
                },
                false,
                { allowNegativeBalance: true },
            );
            currentBalance = currentBalance - usageTotal;
        }
        // in-memory balance used for top-up evaluation after usage deduction
        customer = customer
            ? ({ ...customer, creditBalance: currentBalance.toString() } as ReadCustomerResponseData)
            : customer;
        return this.topUpWithBalance({ customer, currentBalance });
    }

    async topUpWithBalance({
        customer,
        currentBalance,
    }: {
        customer?: ReadCustomerResponseData;
        currentBalance: number;
    }): Promise<string | void> {
        const topUpAmount = parseFloat(this.topUpAmount || '0');
        const topUpThreshold = parseFloat(this.topUpThreshold !== undefined ? this.topUpThreshold : '0.2');
        const thresholdAmount = topUpThreshold * topUpAmount;
        if (currentBalance >= thresholdAmount) {
            return;
        }
        const unitCost = Math.round((topUpAmount - currentBalance) * 100) / 100;
        if (unitCost <= 0) {
            return;
        }
        const lineItems = new InvoiceLineItems();
        lineItems.addLineItem(new InvoiceLineItem(`${this.offeringName} - Top Up`, 1, unitCost));
        const { invoiceId } = await this.invoicesService.create({
            businessID: this.businessID,
            customer,
            customerId: this.customerId,
            items: lineItems,
            invoiceDate: new Date().toISOString(),
            currency: Offering.getCurrency({ customer, offering: this }),
            storePaymentAsCredit: true,
        });
        return invoiceId;
    }

    async offcycleBilling({
        startDate,
        endDate,
        customer,
        invoiceDate,
        invoicePaymentTerm,
        isManual = false,
    }: {
        startDate: Date;
        endDate: Date;
        customer?: ReadCustomerResponseData;
        invoiceDate?: string;
        invoicePaymentTerm?: InvoicePaymentTerm;
        isManual?: boolean;
    }): Promise<string> {
        if (this.billingCycle === ValidBillingCycles.topUp) {
            const invoiceId = await this.processTopUpBilling({ customer, startDate, endDate });
            return invoiceId as string;
        }
        const lineItems = new InvoiceLineItems();
        await Offering.getLineItemsForUsage({
            startDate,
            endDate,
            customer,
            lineItems,
            negative: false,
            businessID: this.businessID,
            customerId: this.customerId,
            customerService: this.customerService,
            offeringInstance: this,
            dimensions: this.dimensions,
        });
        const { invoiceId } = await this.invoicesService.create(
            {
                businessID: this.businessID,
                customer: customer,
                customerId: this.customerId,
                items: lineItems,
                invoiceDate: invoiceDate ? invoiceDate : endDate.toISOString(),
                currency: Offering.getCurrency({ customer, offering: this }),
                invoicePaymentTerm,
            },
            isManual,
        );
        return invoiceId;
    }

