export class CreateInvoicesDto {
    /**
     * The ID for the Business Entity using Paigo
     * @example 123MyCoolCorp980
     */

    @IsString()
    @ApiHideProperty()
    @IsOptional()
    public businessID: string;

    /**
     *
     * The client ID assocaited with the Business Entity, this is the name for the business which will be used in the invoce
     * <br><br>
     * Example: `"Khols"`
     * @example Khols
     */

    @IsString()
    @IsNotEmpty()
    @ApiProperty()
    public customerId: string;

    /**
     *
     * The Itemized collection of elements to be billed. These could be instance compute hours, or number of users
     * <br><br>
     * Example: `[{ "name": "MyService", "quantity": 1, "unitCost": 100.09 }]`
     */

    @ManualInvoiceValidation('items')
    @InvoiceLineItemValidation('items')
    @ApiProperty({
        isArray: true,
        type: 'object',
        example: [{ name: 'Paigo Pro', quantity: 1, unitCost: 100.09 }],
    })
    public items: Array<any> | InvoiceLineItems;

    /**
     * The date the invoice is to be generated for
     * <br><br>
     * Example: `"2020-09-18T17:34:02.666Z"`
     * @example "2020-09-18T17:34:02.666Z"
     */
    @IsOptional()
    @IsDateString()
    @ApiProperty()
    public invoiceDate?: string;

    /**
     * The currency the invoice is to be generated in. If no Currency is passed in the currency used by the customer will be used.
     * <br><br>
     * Example: `"EUR"`
     * @example "EUR"
     *
     */
    @IsOptional()
    @ApiProperty({ enum: SupportedCurrencies })
    public currency?: SupportedCurrencies;

    /**
     *
     * The Payment Term for the invoice. This is the number of days until the invoice is considered past due. Default is "none". String `""` represents "none".
     * <br><br>
     * Example: `"30"`
     * @example '"30"'
     */
    @IsEnum(InvoicePaymentTerm)
    @IsOptional()
    @ApiProperty()
    public invoicePaymentTerm?: InvoicePaymentTerm;

    /**
     * The start time the invoice is to be generated for, if not provided the first day of the current month (UTC) will be used
     * <br><br>
     * Example: `"2020-09-01T13:37:00.000Z"`
     * @example '2020-09-01T13:37:00.000Z'
     */
    @IsRFC3339()
    @IsOptional()
    @StartTimeRangeValidation('start')
    @ApiHideProperty()
    public start?: string;

    /**
     * The end time the invoice is to be generated for, if not provided now in UTC will be used. <br><br>  <i> If provided EndTime must be after startTime and must also be after the first day of the current month </i>
     * <br><br>
     * Example: `"2020-09-18T17:34:02.666Z"`
     * @example '2020-09-18T17:34:02.666Z'
     */
    @IsRFC3339()
    @IsOptional()
    @ApiHideProperty()
    public end?: string;

    @IsOptional()
    @ApiHideProperty()
    public offeringId?: string;

    /**
     * When true, payment for this invoice is stored as customer wallet credit.
     */
    @IsBoolean()
    @IsOptional()
    @ApiHideProperty()
    public storePaymentAsCredit?: boolean;
}

async create(
    {
        businessID,
        customerId,
        items,
        invoiceDate = new Date().toISOString(),
        invoicePaymentTerm,
        currency,
        customer,
        storePaymentAsCredit,
    }: CreateInvoicesDto & CustomerInvoiceDto,
    isManual = false,
): Promise<CreateInvoiceResponseDto> {
    InvoicesService.logger.log(`Creating invoice for business ${businessID}, currency: ${currency}`);
    const newInvoice = await this.buildInvoice({
        businessID,
        customerId,
        items,
        invoiceDate,
        invoicePaymentTerm,
        currency,
        customer,
    });
    newInvoice.storePaymentAsCredit = storePaymentAsCredit;
    const res = await newInvoice.generate(this.taxService, isManual);
    if (storePaymentAsCredit) {
        const creditAmount = newInvoice.totalAmountWithoutTax;
        if (creditAmount > 0) {
            await this.creditService.create(
                {
                    transactionAmount: creditAmount.toFixed(2),
                    customerId,
                    businessID,
                    timestamp: new Date().toISOString(),
                    metadata: {
                        invoiceId: newInvoice.invoiceId,
                        reason: 'Top up credit from invoice payment',
                    },
                },
                false,
            );
        }
    }
    await this.tokenConsumerService.create({
        businessID: businessID,
        metadata: { tokenType: TokenType.invoice, invoiceId: newInvoice?.invoiceId, businessID: businessID },
        tokenAmount: '1',
        timestamp: new Date().toISOString(),
    });
    WebhookPublishingService.publishEvent({
        topic: WebhookProcessorEventType.Standard,
        type: WebhookType.INVOICE_CREATED,
        data: [{ ...res, customerId, offeringIds: customer?.offeringIds }],
        businessID,
    });
    return res;
}

