import socket, threading, sys
# Minimal RESP redis that answers PING/INFO/SUBSCRIBE enough for ioredis/bull
def handle(conn):
    buf = b''
    try:
        while True:
            data = conn.recv(4096)
            if not data:
                break
            buf += data
            # very naive: respond PONG to anything containing PING
            upper = buf.upper()
            if b'PING' in upper:
                conn.sendall(b'+PONG\r\n')
                buf = b''
            elif b'INFO' in upper:
                conn.sendall(b'$11\r\nredis_version:6.2.0\r\n')
                buf = b''
            elif b'AUTH' in upper:
                conn.sendall(b'+OK\r\n')
                buf = b''
            elif b'SELECT' in upper:
                conn.sendall(b'+OK\r\n')
                buf = b''
            elif b'CLUSTER' in upper:
                conn.sendall(b'-ERR unknown\r\n')
                buf = b''
            elif b'COMMAND' in upper:
                conn.sendall(b'*0\r\n')
                buf = b''
            elif b'CLIENT' in upper:
                conn.sendall(b'+OK\r\n')
                buf = b''
            elif b'SUBSCRIBE' in upper or b'PSUBSCRIBE' in upper:
                # bull uses subscriber connection
                conn.sendall(b'*3\r\n$9\r\nsubscribe\r\n$7\r\nchannel\r\n:1\r\n')
                buf = b''
            elif b'CONFIG' in upper:
                conn.sendall(b'*0\r\n')
                buf = b''
            else:
                # default OK for SET etc
                if b'\r\n' in buf:
                    conn.sendall(b'+OK\r\n')
                    buf = b''
    except Exception:
        pass
    finally:
        try: conn.close()
        except: pass

